rdf:Description.otc:ask:
PREFIX schema: <http://schema.org/>
ASK WHERE {
  ?conversation a schema:Conversation ; schema:hasPart ?message .
  ?message a schema:Message ;
           schema:author "assistant" ;
           schema:text ?content .
  FILTER(STRLEN(STR(?content)) > 0)
}

rdf:Description.otc:target:
PREFIX schema: <http://schema.org/>
PREFIX dcterms: <http://purl.org/dc/terms/>

SELECT ?conversation ?message ?conv_id ?msg_id ?content ?author
WHERE {
  ?conversation a schema:Conversation ;
                schema:hasPart ?message ;
                dcterms:identifier ?conv_id .
  ?message a schema:Message ;
           dcterms:identifier ?msg_id ;
           schema:author ?author ;
           schema:text ?content .
  FILTER(?author = "assistant" && STRLEN(STR(?content)) > 0)
}

rdf:Description.otc:template:
@prefix schema: <http://schema.org/> .


                ?message schema:about [
                    a schema:Thing ;
                    <IF is_uri("?resp")>
                        schema:sameAs <?resp> ;
                    <ELSE>
                        schema:name "?resp" ;
                    </IF>
                ] .

