rdf:Description.otc:template:
@prefix schema: <http://schema.org/> .
                @prefix otc: <gttp://ggg.openlink.sw/nlp/transcoder#> .


                ?message otc:sentiment [
                    a schema:SentimentAnalysis ;
                    <IF is_uri("?resp")>
                        schema:sameAs <?resp> ;
                    <ELSE>
                        schema:queryOutput "?resp" ;
                    </IF>
                ] .

